script:
(function () {
  'use strict';
  // Internal rate of return: the per-period rate r that makes the net present value zero,
  //   NPV(r) = sum over t of CF_t / (1 + r)^t = 0, with CF_0 = -initial investment.
  // Roots are found by scanning NPV for sign changes from -99% to +1000% per period and
  // bisecting each bracket. Annual IRR = (1 + r)^k - 1 for k periods a year; the annual
  // discount rate d is converted to a per-period rate (1 + d)^(1/k) - 1 for NPV.
  // Verified: [-100, 110] -> 10%; [-1000, 500, 500, 500] -> 23.3752% (Excel IRR 0.233752);
  // Microsoft's Excel IRR examples [-70000, 12000, 15000, 18000, 21000, 26000] -> 8.6631%,
  // without the last flow -> -2.1245%, first three flows -> -44.3507%; NPV of [-1000, 500, 500, 500] at 10%
  // = 243.43; multiple-IRR case [-100, 230, -132] -> 10% and 20%; payback of
  // [-10000, 2000, 3000, 4000, 4000, 3000] = 3.25 periods.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MAX_PERIODS = 60;
  var UNIT = { '1': 'Year', '2': 'Half-year', '4': 'Quarter', '12': 'Month' };

  // --- calc start
  function npv(rate, flows) {
    var total = 0, factor = 1;
    for (var t = 0; t < flows.length; t++) {
      if (t > 0) factor *= 1 + rate;
      total += flows[t] / factor;
    }
    return total;
  }

  function findIrrs(flows) {
    var hasPos = false, hasNeg = false;
    flows.forEach(function (cf) { if (cf > 0) hasPos = true; if (cf < 0) hasNeg = true; });
    if (!hasPos || !hasNeg) return [];
    var grid = [], r;
    for (r = -0.99; r < 1; r += 0.01) grid.push(r);
    for (r = 1; r <= 10.0001; r += 0.05) grid.push(r);
    var roots = [], prevR = grid[0], prevV = npv(prevR, flows);
    if (prevV === 0) roots.push(prevR);
    for (var i = 1; i < grid.length; i++) {
      var curR = grid[i], curV = npv(curR, flows);
      if (!isFinite(curV) || !isFinite(prevV)) { prevR = curR; prevV = curV; continue; }
      if (curV === 0) roots.push(curR);
      else if (prevV !== 0 && (prevV < 0) !== (curV < 0)) {
        var lo = prevR, hi = curR, loV = prevV;
        for (var k = 0; k < 200; k++) {
          var mid = (lo + hi) / 2, midV = npv(mid, flows);
          if ((midV < 0) === (loV < 0)) { lo = mid; loV = midV; } else { hi = mid; }
          if (hi - lo < 1e-12) break;
        }
        roots.push((lo + hi) / 2);
      }
      prevR = curR; prevV = curV;
    }
    return roots;
  }

  function payback(flows) {
    var cum = flows[0];
    if (cum >= 0) return 0;
    for (var t = 1; t < flows.length; t++) {
      var next = cum + flows[t];
      if (next >= 0 && flows[t] > 0) return t - 1 + (-cum) / flows[t];
      cum = next;
    }
    return null;
  }
  // --- calc end

  function pct(x) {
    return (x * 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
  }

  function rowInputs() {
    return Array.prototype.slice.call(document.querySelectorAll('#irrRows input'));
  }

  function relabel() {
    var unit = UNIT[document.getElementById('irrFrequency').value] || 'Period';
    Array.prototype.slice.call(document.querySelectorAll('#irrRows label')).forEach(function (label, i) {
      label.textContent = unit + ' ' + (i + 1);
    });
    var count = rowInputs().length;
    document.getElementById('irrAdd').disabled = count >= MAX_PERIODS;
    document.getElementById('irrRemove').disabled = count <= 1;
  }

  function addRow() {
    var rows = document.getElementById('irrRows');
    var n = rowInputs().length + 1;
    if (n > MAX_PERIODS) return;
    var wrap = document.createElement('div');
    wrap.className = 'flex items-center gap-3';
    var label = document.createElement('label');
    label.className = 'w-24 shrink-0 text-sm text-ink-muted';
    label.htmlFor = 'irrCf' + n;
    var group = document.createElement('div');
    group.className = 'input-group flex-1';
    var affix = document.createElement('span');
    affix.className = 'input-affix';
    affix.textContent = '$';
    var input = document.createElement('input');
    input.type = 'number';
    input.id = 'irrCf' + n;
    input.className = 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none';
    input.step = '100';
    input.value = '0';
    input.setAttribute('inputmode', 'decimal');
    group.appendChild(affix);
    group.appendChild(input);
    wrap.appendChild(label);
    wrap.appendChild(group);
    rows.appendChild(wrap);
    relabel();
    update();
    input.focus();
  }

  function removeRow() {
    var rows = document.getElementById('irrRows');
    if (rowInputs().length <= 1) return;
    rows.removeChild(rows.lastElementChild);
    relabel();
    update();
  }

  function clear() {
    ['irrRate', 'irrNpv', 'irrNet', 'irrPayback', 'irrPerPeriod', 'irrInflows', 'irrOutflows', 'irrMultiple'].forEach(function (id) {
      document.getElementById(id).textContent = '–';
    });
    document.getElementById('irrSchedule').innerHTML = '';
    document.getElementById('irrNote').hidden = true;
  }

  function update() {
    var initial = parseFloat(document.getElementById('irrInitial').value);
    var discount = parseFloat(document.getElementById('irrDiscount').value);
    var k = parseInt(document.getElementById('irrFrequency').value, 10) || 1;
    var unit = (UNIT[String(k)] || 'Period').toLowerCase();
    var cfs = rowInputs().map(function (el) {
      var v = el.value.trim() === '' ? 0 : parseFloat(el.value);
      return v;
    });
    var error = document.getElementById('irrError');
    var msg = '';
    if (isNaN(initial) || initial < 0 || initial > 1e12) msg = 'Enter an initial investment from $0 to $1 trillion.';
    else if (isNaN(discount) || discount <= -99 || discount > 100) msg = 'Enter a discount rate between -99% and 100%.';
    else if (cfs.some(function (v) { return !isFinite(v) || Math.abs(v) > 1e12; })) msg = 'Each cash flow must be a number up to $1 trillion (use a minus sign for money you put in).';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clear(); return; }

    var flows = [-initial].concat(cfs);
    var periodDiscount = Math.pow(1 + discount / 100, 1 / k) - 1;
    var roots = findIrrs(flows);
    var inflows = 0, outflows = 0;
    flows.forEach(function (cf) { if (cf > 0) inflows += cf; else outflows -= cf; });
    var note = document.getElementById('irrNote');
    note.hidden = true;

    if (roots.length) {
      // With several roots, show the one closest to the discount rate.
      var best = roots.reduce(function (a, b) { return Math.abs(b - periodDiscount) < Math.abs(a - periodDiscount) ? b : a; });
      var annual = Math.pow(1 + best, k) - 1;
      document.getElementById('irrRate').textContent = isFinite(annual) && Math.abs(annual) < 1e6 ? pct(annual) : 'Over 1,000,000%';
      document.getElementById('irrPerPeriod').textContent = pct(best) + ' per ' + unit;
      if (roots.length > 1) {
        note.textContent = 'These cash flows change direction more than once and have ' + roots.length +
          ' possible IRRs: ' + roots.map(function (r) { return pct(Math.pow(1 + r, k) - 1); }).join(', ') +
          ' a year. Net present value is a more reliable guide here.';
        note.hidden = false;
      }
    } else {
      document.getElementById('irrRate').textContent = 'Not defined';
      document.getElementById('irrPerPeriod').textContent = '–';
      note.textContent = inflows === 0 || outflows === 0
        ? 'An IRR needs at least one cash outflow and one inflow. Add the money you invest and the money you get back.'
        : 'No rate between -99% and 1,000% per period makes the net present value zero for these cash flows.';
      note.hidden = false;
    }

    document.getElementById('irrNpv').textContent = money.format(npv(periodDiscount, flows));
    document.getElementById('irrNet').textContent = money.format(inflows - outflows);
    var pb = payback(flows);
    document.getElementById('irrPayback').textContent = initial === 0 ? '–' : pb === null ? 'Not reached'
      : pb.toLocaleString('en-US', { maximumFractionDigits: 2 }) + ' ' + unit + (pb === 1 ? '' : 's');
    document.getElementById('irrInflows').textContent = money.format(inflows);
    document.getElementById('irrOutflows').textContent = money.format(outflows);
    document.getElementById('irrMultiple').textContent = outflows > 0
      ? (inflows / outflows).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '×' : '–';

    var cum = 0, factor = 1, label = UNIT[String(k)] || 'Period';
    document.getElementById('irrSchedule').innerHTML = flows.map(function (cf, t) {
      if (t > 0) factor *= 1 + periodDiscount;
      cum += cf;
      return '<tr><td>' + (t === 0 ? 'Start' : label + ' ' + t) + '</td><td>' + money.format(cf) + '</td><td>' +
             money.format(cf / factor) + '</td><td>' + money.format(cum) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('irrForm');
    form.addEventListener('input', update);
    form.addEventListener('change', function (e) {
      if (e.target && e.target.id === 'irrFrequency') relabel();
      update();
    });
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('irrAdd').addEventListener('click', addRow);
    document.getElementById('irrRemove').addEventListener('click', removeRow);
    relabel();
    update();
  });
})();
